export function cursorLabels(lang) {
  const out = {};
  for (const k in CURSOR) out[k] = CURSOR[k][lang] || CURSOR[k].pt;
  return out;
}

export function getLang() {
  try { return localStorage.getItem('nq_lang') || 'pt'; } catch (e) { return 'pt'; }
}
export function setLang(l) {
  try { localStorage.setItem('nq_lang', l); } catch (e) {}
}

